{"path":"src/App.tsx","content":"import { useEffect, useMemo, useState } from 'react'
import { CITIES, CITY_MAP, DEFAULT_CITY_IDS } from './data/cities'
import { formatMinutes, getOffsetMinutes, isAwake, localMinutesForRefHour, type Mode, type TimeFormat } from './lib/time'
import type { RowData } from './lib/types'
import AddCity from './components/AddCity'
import SettingsPanel from './components/SettingsPanel'
import OverlapSummary from './components/OverlapSummary'
import DesktopGrid from './components/DesktopGrid'
import MobileGrid from './components/MobileGrid'

const STORAGE_KEY = 'timezone-overlap-checker:v1'

interface PersistedState {
  cityIds: string[]
  mode: Mode
  wake: number
  sleep: number
  timeFormat: TimeFormat
}

function loadState(): PersistedState {
  const fallback: PersistedState = { cityIds: DEFAULT_CITY_IDS, mode: 'meeting', wake: 7, sleep: 23, timeFormat: '12h' }
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return fallback
    const parsed = JSON.parse(raw) as Partial<PersistedState>
    const cityIds = Array.isArray(parsed.cityIds)
      ? parsed.cityIds.filter((id): id is string => typeof id === 'string' && CITY_MAP.has(id))
      : []
    return {
      cityIds: cityIds.length > 0 ? [...new Set(cityIds)] : fallback.cityIds,
      mode: parsed.mode === 'base' ? 'base' : 'meeting',
      wake: typeof parsed.wake === 'number' && parsed.wake >= 0 && parsed.wake <= 23 ? parsed.wake : 7,
      sleep: typeof parsed.sleep === 'number' && parsed.sleep >= 0 && parsed.sleep <= 23 ? parsed.sleep : 23,
      timeFormat: parsed.timeFormat === '24h' ? '24h' : '12h',
    }
  } catch {
    return fallback
  }
}

function useIsMobile() {
  const [mobile, setMobile] = useState(() => typeof window !== 'undefined' && window.innerWidth < 768)
  useEffect(() => {
    const mq = window.matchMedia('(max-width: 767px)')
    const update = () => setMobile(mq.matches)
    update()
    mq.addEventListener('change', update)
    window.addEventListener('resize', update)
    return () => {
      mq.removeEventListener('change', update)
      window.removeEventListener('resize', update)
    }
  }, [])
  return mobile
}

export default function App() {
  const [initial] = useState<PersistedState>(loadState)
  const [cityIds, setCityIds] = useState<string[]>(initial.cityIds)
  const [mode, setMode] = useState<Mode>(initial.mode)
  const [wake, setWake] = useState(initial.wake)
  const [sleep, setSleep] = useState(initial.sleep)
  const [timeFormat, setTimeFormat] = useState<TimeFormat>(initial.timeFormat)
  const isMobile = useIsMobile()

  useEffect(() => {
    try {
      const state: PersistedState = { cityIds, mode, wake, sleep, timeFormat }
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state))
    } catch {
      // storage unavailable
    }
  }, [cityIds, mode, wake, sleep, timeFormat])

  const cities = useMemo(() => cityIds.map((id) => CITY_MAP.get(id)!).filter(Boolean), [cityIds])
  const reference = cities[0]

  const offsets = useMemo(() => {
    const now = new Date()
    const map = new Map<string, number>()
    for (const c of CITIES) map.set(c.id, getOffsetMinutes(c.timezone, now))
    return map
  }, [])

  const refOffset = reference ? (offsets.get(reference.id) ?? 0) : 0

  // awake matrix: [cityId][refHour] => boolean
  const awakeMatrix = useMemo(() => {
    const map = new Map<string, boolean[]>()
    for (const city of cities) {
      const off = offsets.get(city.id) ?? 0
      const arr: boolean[] = []
      for (let h = 0; h < 24; h++) {
        const local = localMinutesForRefHour(h, refOffset, off)
        arr.push(isAwake(local, wake, sleep))
      }
      map.set(city.id, arr)
    }
    return map
  }, [cities, offsets, refOffset, wake, sleep])

  const meetingOverlap = useMemo(() => {
    if (cities.length === 0) return []
    const result: number[] = []
    for (let h = 0; h < 24; h++) {
      if (cities.every((c) => awakeMatrix.get(c.id)?.[h])) result.push(h)
    }
    return result
  }, [cities, awakeMatrix])

  const baseOverlaps = useMemo(() => {
    const map = new Map<string, number[]>()
    if (!reference) return map
    const refAwake = awakeMatrix.get(reference.id) ?? []
    for (const city of cities.slice(1)) {
      const arr: number[] = []
      const cityAwake = awakeMatrix.get(city.id) ?? []
      for (let h = 0; h < 24; h++) {
        if (refAwake[h] && cityAwake[h]) arr.push(h)
      }
      map.set(city.id, arr)
    }
    return map
  }, [cities, reference, awakeMatrix])

  const rows: RowData[] = useMemo(() => {
    return cities.map((city, idx) => {
      const off = offsets.get(city.id) ?? 0
      const cells = Array.from({ length: 24 }, (_, h) => {
        const localMinutes = localMinutesForRefHour(h, refOffset, off)
        const awake = awakeMatrix.get(city.id)?.[h] ?? false
        let isOverlap = false
        if (awake) {
          if (mode === 'meeting') isOverlap = meetingOverlap.includes(h)
          else if (idx === 0) isOverlap = true
          else isOverlap = (baseOverlaps.get(city.id) ?? []).includes(h)
        }
        return {
          refHour: h,
          localMinutes,
          label: formatMinutes(localMinutes, timeFormat),
          awake,
          isOverlap,
          state: (!awake ? 'sleeping' : isOverlap ? 'overlap' : 'awake') as 'sleeping' | 'awake' | 'overlap',
        }
      })
      return { city, offset: off, cells }
    })
  }, [cities, offsets, refOffset, awakeMatrix, mode, meetingOverlap, baseOverlaps, timeFormat])

  function addCity(id: string) {
    setCityIds((prev) => (prev.includes(id) ? prev : [...prev, id]))
  }
  function removeCity(id: string) {
    setCityIds((prev) => (prev.length <= 1 ? prev : prev.filter((c) => c !== id)))
  }
  function promoteCity(id: string) {
    setCityIds((prev) => {
      if (!prev.includes(id) || prev[0] === id) return prev
      return [id, ...prev.filter((c) => c !== id)]
    })
  }

  return (
    <div className="app">
      <header className="topbar">
        <div className="topbar-inner">
          <div>
            <h1>muse-wonder-1.0</h1>
            <p className="subtitle">Timezone overlap checker — find hours when everyone is awake.</p>
          </div>
          <div className="mode-toggle" role="group" aria-label="Mode">
            <button type="button" className={mode === 'meeting' ? 'mode-btn active' : 'mode-btn'} onClick={() => setMode('meeting')} aria-pressed={mode === 'meeting'}>Meeting Mode</button>
            <button type="button" className={mode === 'base' ? 'mode-btn active' : 'mode-btn'} onClick={() => setMode('base')} aria-pressed={mode === 'base'}>Base Mode</button>
          </div>
        </div>
        <p className="mode-desc">
          {mode === 'meeting'
            ? 'Meeting Mode: one shared window when every city is awake at the same time.'
            : `Base Mode: each city is compared only against ${reference?.name ?? 'the reference'}.`}
        </p>
      </header>

      <main className="main">
        <section className="controls card">
          <div className="controls-row">
            <AddCity selectedIds={cityIds} onAdd={addCity} />
            <span className="controls-hint">Click a city name to make it the reference. All hours are anchored to the reference city.</span>
          </div>
          <SettingsPanel wake={wake} sleep={sleep} timeFormat={timeFormat} onWake={setWake} onSleep={setSleep} onFormat={setTimeFormat} />
          <div className="legend" aria-label="Legend">
            <span className="legend-item"><span className="swatch swatch--overlap" /> Overlap</span>
            <span className="legend-item"><span className="swatch swatch--awake" /> Awake</span>
            <span className="legend-item"><span className="swatch swatch--sleeping" /> Sleeping</span>
            <span className="legend-note">Awake window: {timeFormat === '12h' ? '' : ''}{wake}–{sleep} applies to every city.</span>
          </div>
        </section>

        <OverlapSummary mode={mode} cities={cities} meetingOverlap={meetingOverlap} baseOverlaps={baseOverlaps} timeFormat={timeFormat} referenceName={reference?.name ?? ''} />

        <section className="grid-card card" aria-label="Timezone grid">
          {reference && (
            <p className="grid-caption">
              Columns are hours in <strong>{reference.name}</strong> ({timeFormat === '12h' ? '12-hour' : '24-hour'}). Each cell shows the local time in that city.
            </p>
          )}
          {isMobile ? (
            <MobileGrid rows={rows} timeFormat={timeFormat} onPromote={promoteCity} onRemove={removeCity} />
          ) : (
            <DesktopGrid rows={rows} timeFormat={timeFormat} onPromote={promoteCity} onRemove={removeCity} />
          )}
        </section>

        <p className="hint">
          {mode === 'meeting' ? 'Green cells = everyone awake' : `Green cells = overlapping with ${reference?.name ?? 'reference'}`}
        </p>
        {mode === 'base' && <p className="hint secondary">In Base Mode each row highlights its own overlap with the reference city, so rows can differ.</p>}
      </main>

      <footer className="footer">Offsets use the current date, so daylight saving time is handled automatically. Fractional offsets (e.g. India, Nepal) are supported.</footer>
    </div>
  )
}
"}

{"path":"src/index.css","content":":root {
  --bg: #e9ebe4;
  --ink: #1a2620;
  --muted: #6b7a70;
  --card: #ffffff;
  --line: #d8ddd2;
  --dark: #14231e;
  --green: #0e9f6e;
  --green-dark: #0b7a55;
  --green-bg: #12b981;
  --awake-bg: #f4f5ef;
  --sleep-bg: #e9eae6;
  --sleep-ink: #a3ada5;
  --amber-bg: #fff4d6;
  --amber-ink: #7a5a00;
  --amber-line: #f0d48a;
  font-family: "Avenir Next", Avenir, "Segoe UI", system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--bg);
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); }
button, select, input { font: inherit; }
h1 { font-family: Georgia, "Times New Roman", serif; font-weight: 700; letter-spacing: -0.02em; }

.app { min-height: 100vh; display: flex; flex-direction: column; }
.topbar { background: var(--dark); color: #f2f5ef; padding: 22px 20px 16px; }
.topbar-inner { max-width: 1240px; margin: 0 auto; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; flex-wrap: wrap; }
.topbar h1 { margin: 0; font-size: 34px; line-height: 1; color: #fff; }
.subtitle { margin: 8px 0 0; color: #b9c8bd; font-size: 15px; max-width: 520px; line-height: 1.45; }
.mode-desc { max-width: 1240px; margin: 14px auto 0; color: #9fb3a4; font-size: 13.5px; }
.mode-toggle { display: inline-flex; background: #22352d; border: 1px solid #355344; border-radius: 999px; padding: 4px; gap: 4px; }
.mode-btn { border: 0; background: transparent; color: #cfe0d3; padding: 8px 16px; border-radius: 999px; cursor: pointer; font-weight: 600; font-size: 14px; }
.mode-btn.active { background: #fff; color: var(--dark); }

.main { max-width: 1240px; width: 100%; margin: 0 auto; padding: 18px 16px 8px; display: flex; flex-direction: column; gap: 14px; flex: 1; }
.card { background: var(--card); border: 1px solid var(--line); border-radius: 14px; }
.controls { padding: 16px; display: flex; flex-direction: column; gap: 14px; }
.controls-row { display: flex; align-items: center; gap: 14px; flex-wrap: wrap; }
.controls-hint { color: var(--muted); font-size: 13px; }
.add-city { position: relative; }
.add-city-btn { background: var(--dark); color: #fff; border: 0; border-radius: 999px; padding: 9px 16px; font-weight: 700; cursor: pointer; }
.add-city-btn:hover { background: #1e3a30; }
.add-city-panel { position: absolute; z-index: 40; top: calc(100% + 8px); left: 0; width: 320px; max-width: 86vw; background: #fff; border: 1px solid var(--line); border-radius: 12px; box-shadow: 0 16px 40px rgba(20,35,30,.18); overflow: hidden; }
.add-city-search { width: 100%; padding: 11px 12px; border: 0; border-bottom: 1px solid var(--line); outline: none; }
.add-city-list { list-style: none; margin: 0; padding: 6px; max-height: 320px; overflow: auto; }
.add-city-item { width: 100%; display: flex; justify-content: space-between; gap: 12px; text-align: left; background: transparent; border: 0; padding: 9px 10px; border-radius: 8px; cursor: pointer; }
.add-city-item:hover { background: #eef3ec; }
.add-city-item-name { font-weight: 650; }
.add-city-item-meta { color: var(--muted); font-size: 12.5px; }
.add-city-empty { padding: 12px; color: var(--muted); }

.settings { display: flex; gap: 18px; flex-wrap: wrap; align-items: end; border-top: 1px solid var(--line); padding-top: 14px; }
.setting { display: flex; flex-direction: column; gap: 6px; }
.setting label, .setting-label { font-size: 12px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }
.setting select { padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: #fff; min-width: 150px; }
.segmented { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; padding: 3px; gap: 3px; }
.seg { border: 0; background: transparent; padding: 6px 14px; border-radius: 999px; cursor: pointer; font-weight: 650; }
.seg.active { background: var(--dark); color: #fff; }
.legend { display: flex; gap: 16px; flex-wrap: wrap; align-items: center; font-size: 13px; color: var(--muted); }
.legend-item { display: inline-flex; gap: 6px; align-items: center; }
.swatch { width: 14px; height: 14px; border-radius: 4px; display: inline-block; border: 1px solid var(--line); }
.swatch--overlap { background: var(--green-bg); border-color: var(--green-dark); }
.swatch--awake { background: var(--awake-bg); }
.swatch--sleeping { background: var(--sleep-bg); }

.summary { background: #eef6f0; border: 1px solid #cfe6d6; border-radius: 14px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; }
.summary-main { display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap; }
.summary-label { font-size: 12px; font-weight: 800; letter-spacing: .05em; text-transform: uppercase; color: var(--green-dark); }
.summary-count { font-size: 20px; }
.summary-ref { color: var(--muted); font-size: 13px; }
.summary-warning { margin: 0; background: var(--amber-bg); border: 1px solid var(--amber-line); color: var(--amber-ink); padding: 8px 10px; border-radius: 8px; font-size: 13.5px; }
.summary-warning.inline { padding: 3px 8px; }
.range-badges { display: flex; gap: 8px; flex-wrap: wrap; }
.range-badges.inline-badges { display: inline-flex; }
.range-badge { background: var(--dark); color: #fff; padding: 5px 10px; border-radius: 999px; font-size: 13px; font-weight: 700; white-space: nowrap; }
.base-lines { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 8px; }
.base-line { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; font-size: 14px; }
.base-line-city { font-weight: 650; }

.grid-card { padding: 14px; overflow: hidden; }
.grid-caption { margin: 0 0 12px; color: var(--muted); font-size: 13.5px; }
.desktop-grid { display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.grid-header-row, .city-row { display: grid; grid-template-columns: 188px minmax(0,1fr) 34px; gap: 10px; align-items: center; }
.grid-corner { font-size: 11px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--muted); }
.hour-header { display: grid; grid-template-columns: repeat(24, minmax(0,1fr)); gap: 3px; }
.hour-label { text-align: center; font-size: 10.5px; color: var(--muted); font-weight: 650; white-space: nowrap; overflow: hidden; }
.cells { display: grid; grid-template-columns: repeat(24, minmax(0,1fr)); gap: 3px; }
.cell { text-align: center; padding: 8px 0; border-radius: 6px; font-size: 11.5px; line-height: 1; white-space: nowrap; overflow: hidden; border: 1px solid transparent; }
.cell--sleeping { background: var(--sleep-bg); color: var(--sleep-ink); }
.cell--awake { background: var(--awake-bg); color: var(--ink); border-color: #eef0e8; }
.cell--overlap { background: var(--green-bg); color: #fff; font-weight: 800; border-color: var(--green-dark); }
.city-info { display: flex; align-items: center; gap: 7px; flex-wrap: wrap; min-width: 0; }
.city-name-btn { background: none; border: 0; padding: 0; font-weight: 750; cursor: pointer; color: var(--ink); text-align: left; }
.city-name-btn:hover { text-decoration: underline; }
.city-name-btn.small { font-size: 12px; }
.ref-badge { background: var(--green-dark); color: #fff; font-size: 10px; font-weight: 800; letter-spacing: .06em; padding: 2px 6px; border-radius: 999px; }
.city-meta { color: var(--muted); font-size: 12px; }
.utc-offset { font-size: 12px; font-weight: 700; background: #eef1ea; border: 1px solid var(--line); padding: 2px 6px; border-radius: 999px; white-space: nowrap; }
.utc-offset.small { font-size: 10.5px; }
.remove-btn { width: 30px; height: 30px; border-radius: 999px; border: 1px solid var(--line); background: #fff; cursor: pointer; font-size: 18px; line-height: 1; color: var(--muted); display: grid; place-items: center; }
.remove-btn:hover { background: #fee2e2; color: #991b1b; border-color: #fecaca; }
.remove-btn.small { width: 22px; height: 22px; font-size: 14px; }

.mobile-grid { display: none; }
.hint { text-align: center; color: var(--muted); font-size: 13.5px; margin: 2px 0; }
.hint.secondary { margin-top: -8px; font-size: 12.5px; }
.footer { text-align: center; color: var(--muted); font-size: 12.5px; padding: 18px 16px 26px; }

@media (max-width: 767px) {
  .topbar h1 { font-size: 28px; }
  .grid-header-row, .city-row { grid-template-columns: 1fr; }
  .desktop-grid { display: none; }
  .mobile-grid { display: flex; flex-direction: column; gap: 3px; }
  .mobile-header, .mobile-row { display: grid; gap: 3px; align-items: stretch; }
  .mobile-header { margin-bottom: 6px; }
  .mobile-corner { font-size: 10px; font-weight: 700; color: var(--muted); text-transform: uppercase; display: flex; align-items: end; }
  .mobile-city-head { display: flex; flex-direction: column; gap: 4px; align-items: center; text-align: center; padding: 6px 2px; background: #f7f8f3; border: 1px solid var(--line); border-radius: 8px; }
  .mobile-hour-label { font-size: 11px; font-weight: 700; color: var(--muted); display: flex; align-items: center; }
  .mobile-grid .cell { padding: 7px 0; font-size: 10.5px; }
  .settings { flex-direction: column; align-items: stretch; }
  .setting select { width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}
"}

